struct pll_param{
	unsigned int freq ;
	unsigned int refdiv ;
	unsigned int postdiv2 ;
	unsigned int postdiv1 ;
	unsigned int FBdiv ;
};

/* freq = freq_xtal / refdiv * fbdiv / posdiv1 / posdiv2
 * freq_xtal = 24 MHz or 27 Mhz
 * postdiv1 must >= postdiv2
 * */
