unsigned int get_pll_config(unsigned int freq)
{
	struct pll_param *p_pll_param_mini;
	unsigned int pll_param_mini_size = 0;
	int i = 0;

#ifdef CONFIG_24M_XTAL
	p_pll_param_mini = pll_param_mini_24mhz;
	pll_param_mini_size = sizeof(pll_param_mini_24mhz)/sizeof(struct pll_param);
#else
	p_pll_param_mini = pll_param_mini_27mhz;
	pll_param_mini_size = sizeof(pll_param_mini_27mhz)/sizeof(struct pll_param);
#endif
	for (i = 0; i < pll_param_mini_size; i++) {
		if (freq == p_pll_param_mini[i].freq) {
			unsigned int bp = 0 ;
			unsigned int refdiv = p_pll_param_mini[i].refdiv ;
			unsigned int postdiv2 = p_pll_param_mini[i].postdiv2 ;
			unsigned int postdiv1 = p_pll_param_mini[i].postdiv1 ;
			unsigned int FBdiv = p_pll_param_mini[i].FBdiv ;

			return (bp<<26)|(refdiv<<20)|(postdiv2<<16)|(postdiv1<<12)|FBdiv;
		}
	}

}

unsigned int get_inno_pll_config(unsigned int freq)
{
       struct pll_param *p_pll_param_mini;
       unsigned int pll_param_mini_size = 0;
       int i = 0;

#ifdef CONFIG_24M_XTAL
       p_pll_param_mini = pll_param_mini_24mhz;
       pll_param_mini_size = sizeof(pll_param_mini_24mhz)/sizeof(struct pll_param);
#else
       p_pll_param_mini = pll_param_mini_27mhz;
       pll_param_mini_size = sizeof(pll_param_mini_27mhz)/sizeof(struct pll_param);
#endif

       for (i = 0; i < pll_param_mini_size; i++) {
               if (freq == p_pll_param_mini[i].freq) {
                       unsigned int refdiv = p_pll_param_mini[i].refdiv ;
                       unsigned int postdiv2 = p_pll_param_mini[i].postdiv2 - 1;
                       unsigned int postdiv1 = p_pll_param_mini[i].postdiv1 - 1;

                       unsigned int FBdiv = p_pll_param_mini[i].FBdiv ;

			return (refdiv<<18)|(postdiv2<<26)|(postdiv1<<23)|(postdiv2<<15)|(postdiv1<<12)|FBdiv;
               }
       }
}

#ifndef BOOTLOADER
#define PLL_DTO_CLK		(1188000000)
#define PLL_CPU_CLK		(729000000)

spl_clock_info spl_clock;

void pll_mini_init(void)
{
	spl_clock.extern_clock_xtal = DEFAULT_EXT_CLOCK_XTAL;
	spl_clock.dto_pll_config = get_pll_config(PLL_DTO_CLK);
#ifdef DDR_PLL_USE_INNO
	spl_clock.ddr_pll_config = get_inno_pll_config(DDR_FREQUENCY_CONFIG);
#else
	spl_clock.ddr_pll_config = get_pll_config(DDR_FREQUENCY_CONFIG);
#endif
	spl_clock.ddr_pll_config_backup = 0;
	spl_clock.cpu_pll_config = get_pll_config(PLL_CPU_CLK);
	spl_clock.arm_debug_clk_div = 8; // ARM debug_pclk, PLL_CPU_CLK/div6 8:div6 4:div4 2:div3 0:div2
	spl_clock.arm_axi_clk_div = 0;  //ARM AXI clock div PLL_CPU_CLK/div2 8:div6 4:div4 2:div3 0:div2
	spl_clock.ahb0_clk_div = 7; //AHB0 1188/(7+1) = 148.5MHz
	spl_clock.ahb1_clk_div = 7; //AHB1 1188/(7+1) = 148.5MHz
	spl_clock.ahb2_clk_div = 7; //AHB2 1188/(7+1) = 148.5MHz
	spl_clock.ahb3_clk_div = 7; //AHB3 1188/(7+1) = 148.5MHz
	spl_clock.secure_clk_div = 7; //Secure ctrl 1188/(7+1) = 148.5MHz
	spl_clock.secure_clk_src = 1; //1: switch secure clk to PLL  0: switch clk to xtal
	spl_clock.apb0_clk_div = 0x01745D17; //APB2_0 27MHz
	spl_clock.apb2_clk_div = 0x01999999; //APB2_2 29.7MHz
	spl_clock.spi_clk_div = 3; // DW SPI 1188/(3+1)=297MHz
#ifdef DDR_PLL_USE_INNO
	spl_clock.ddr_pll_use_inno = 1;
#else
	spl_clock.ddr_pll_use_inno = 0;
#endif
}
#endif
